<?php
require __DIR__.'/../includes/core.php';require_login(['admin','management']);$id=(int)($_GET['id']??0);
$a=one("SELECT a.*,m.name module_name,m.rating_direction,t.name teacher,t.staff_id,t.gender,t.classes,t.subjects,e.name evaluator,s.name session_name,c.term FROM assignments a JOIN modules m ON m.id=a.module_id JOIN users t ON t.id=a.subject_id JOIN users e ON e.id=a.evaluator_id JOIN evaluation_cycles c ON c.id=a.cycle_id JOIN academic_sessions s ON s.id=c.session_id WHERE a.id=? AND a.status='submitted'",[$id]);
if(!$a){http_response_code(404);exit('Report not found');}$sc=score_assignment($id);$comments=one('SELECT * FROM evaluation_comments WHERE assignment_id=?',[$id])??[];$school=school_settings();
$ratings=all('SELECT s.id section_id,s.title section_title,c.id criterion_id,c.title criterion_title,r.rating,o.label rating_label,d.description rating_description FROM responses r JOIN criteria c ON c.id=r.criterion_id JOIN template_sections s ON s.id=c.section_id JOIN rating_options o ON o.module_id=s.module_id AND o.rating=r.rating LEFT JOIN rating_descriptions d ON d.criterion_id=c.id AND d.rating=r.rating WHERE r.assignment_id=? ORDER BY s.sort_order,s.id,c.sort_order,c.id',[$id]);
$bySection=[];foreach($ratings as $r)$bySection[$r['section_title']][]=$r;
ob_start();?><div class="print-toolbar actions"><button type="button" onclick="window.print()">Print / Save as PDF</button><a class="btn alt" href="<?=url('management/reports.php')?>">Back to results</a></div>
<article class="card report-paper"><div class="report-letterhead"><?php if(school_logo_url()):?><img src="<?=h(school_logo_url())?>" alt="School logo"><?php endif;?><h2><?=h($school['school_name'])?></h2><?php if($school['school_motto']):?><p><em><?=h($school['school_motto'])?></em></p><?php endif;?><?php foreach(['school_address','school_phone','school_email','school_website'] as $key):?><?php if(!empty($school[$key])):?><p><?=nl2br(h($school[$key]))?></p><?php endif;?><?php endforeach;?><p class="report-confidential">Confidential Management Evaluation Report</p></div>
<h2><?=h($a['module_name'])?> — Detailed Evaluation</h2><div class="report-meta"><div><b>Teacher:</b> <?=h($a['teacher'])?></div><div><b>Evaluator:</b> <?=h($a['evaluator'])?></div><div><b>Staff ID:</b> <?=h($a['staff_id']?:'—')?></div><div><b>Gender:</b> <?=h($a['gender']?:'—')?></div><div><b>Session:</b> <?=h($a['session_name'])?></div><div><b>Term:</b> <?=h($a['term'])?></div><div><b>Class:</b> <?=h($a['class_name']?:$a['classes']?:'—')?></div><div><b>Subject:</b> <?=h($a['subject_name']?:$a['subjects']?:'—')?></div><div><b>Observation date:</b> <?=h($a['observation_date']?:'—')?></div><div><b>Period:</b> <?=h($a['period_name']?:'—')?></div><div><b>Submitted:</b> <?=h($a['submitted_at'])?></div><div><b>Report Ref:</b> BGB360-<?=str_pad((string)$id,6,'0',STR_PAD_LEFT)?></div></div>
<div class="report-score"><span>Overall evaluation score</span><br><strong><?=number_format($sc['weighted_percent'],2)?>%</strong><p>Converted raw score: <?=h($sc['raw'])?> / <?=h($sc['max'])?> (<?=number_format($sc['raw_percent'],2)?>%)</p><small><?= $a['rating_direction']==='low'?'Lower selected rating numbers represent better performance; converted scores are used for percentage calculation.':'Higher selected rating numbers represent better performance.'?></small></div>
<h3>Section Grading Summary</h3><div class="tablewrap"><table class="report-table"><thead><tr><th>Section</th><th>Score</th><th>Section %</th><th>Weight</th><th>Rated</th></tr></thead><tbody><?php foreach($sc['sections'] as $sec):?><tr><td><?=h($sec['section'])?></td><td><?=$sec['score']?> / <?=$sec['max']?></td><td><?=number_format($sec['percent'],2)?>%</td><td><?=number_format($sec['weight'],2)?>%</td><td><?=$sec['complete']?> / <?=$sec['count']?></td></tr><?php endforeach;?></tbody></table></div>
<h3>All Criteria and Selected Grades</h3><?php foreach($bySection as $section=>$items):?><section class="report-section"><h3><?=h($section)?></h3><table class="report-table"><thead><tr><th style="width:6%">#</th><th>Assessment Indicator</th><th style="width:24%">Selected Grade</th></tr></thead><tbody><?php foreach($items as $idx=>$r):?><tr><td><?=$idx+1?></td><td><?=h($r['criterion_title'])?></td><td><strong><?=h($r['rating'].' — '.$r['rating_label'])?></strong><?php if($r['rating_description']):?><div class="small"><?=h($r['rating_description'])?></div><?php endif;?></td></tr><?php endforeach;?></tbody></table></section><?php endforeach;?>
<?php foreach(['strengths'=>'Strengths Observed','improvements'=>'Suggestions for Improvement','impression'=>'Overall Impression','remarks'=>'Supervisor / Evaluator Remarks'] as $k=>$heading):?><?php if(!empty($comments[$k])):?><section class="report-section"><h3><?=h($heading)?></h3><p class="report-comments"><?=nl2br(h($comments[$k]))?></p></section><?php endif;?><?php endforeach;?><footer class="report-footer"><?=nl2br(h($school['report_footer']))?><?php if($school['school_head']):?><p>School Head: <?=h($school['school_head'])?></p><?php endif;?></footer></article>
<?php layout('Confidential Evaluation Report',ob_get_clean());
